const out=document.getElementById('out');const field=(id)=>document.getElementById(id).value.trim();const headers=()=>({Authorization:'Bearer '+field('token'),'Content-Type':'application/json'});async function adminApi(path,options={}){options.headers=Object.assign(headers(),options.headers||{});const response=await fetch(path,options);const data=await response.json();if(!response.ok)throw new Error(data.error?.message||'Request failed');return data}function show(value){out.textContent=JSON.stringify(value,null,2)}async function createApp(){try{show(await adminApi('/v1/apps',{method:'POST',body:JSON.stringify({app_id:field('app'),name:field('appName')})}))}catch(error){show({error:error.message})}}async function createLicense(){try{const body={app_id:field('app')};const expiry=field('expiry');if(expiry)body.expires_at=expiry;show(await adminApi('/v1/licenses',{method:'POST',body:JSON.stringify(body)}))}catch(error){show({error:error.message})}}async function listApplications(){try{show(await adminApi('/v1/apps'))}catch(error){show({error:error.message})}}async function listLicenses(){try{show(await adminApi('/v1/licenses?app_id='+encodeURIComponent(field('app'))))}catch(error){show({error:error.message})}}
